package main
import "fmt"

func inverter_vetor(lista []int) []int {
        for i, i2 := 0 , len(lista) - 1; i < i2 ; i, i2=i+1, i2-1 {
        lista[i], lista[i2] = lista[i2], lista[i]
}
        return lista
}
func main() {
    var n int
    fmt.Scan(&n)
    fmt.Print("[")
    lista := make([]int, n)
    for i := 0 ; i < n ; i++ {
        fmt.Scan(&lista[i])
    }

    inverter_vetor(lista)

    for _, elem := range lista{
        fmt.Print(" ", elem)
    }
        fmt.Print(" ]\n")
}
